def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator row or column.
    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1), None)
    if sep_row is not None:
        top, bottom = grid[:sep_row], grid[sep_row + 1:]
        return [
            [3 if top[r][c] == 2 and bottom[r][c] == 2 else 2
             for c in range(w)]
            for r in range(min(len(top), len(bottom)))
        ]

    sep_col = next((c for c in range(w)
                    if all(grid[r][c] == grid[0][c] for r in range(h))), None)
    left_width = sep_col
    right_start = sep_col + 1
    width = min(left_width, w - right_start)
    return [
        [3 if grid[r][c] == 2 and grid[r][right_start + c] == 2 else 2
         for c in range(width)]
        for r in range(h)
    ]
